# portutils.py
def is_valid_port(port):
    if isinstance(port, int) and 1 <= port <= 65535:
        return True
    return False

def get_common_ports():
    return [21, 22, 23, 25, 53, 80, 110, 143, 443, 993, 995, 3306, 3389, 8080]

# test_ports.py
import portutils

if __name__ == '__main__':
    print("Common ports:", portutils.get_common_ports())
    test_vals = [80, 99999, 'abc', 22, -5, 443]
    for val in test_vals:
        valid = portutils.is_valid_port(val)
        print(f"{val} is valid: {valid}")
